/**
 * navdata.js — the precached airport / runway / navaid bundle.
 *
 * NO PANEL IN v1 CONSUMES THIS. The HSI and the nav pages are v2, gated behind
 * the attitude stability test. It is here because the bundle is precached by
 * the service worker and BITE has to be able to say whether it is present —
 * "the offline database is missing" is a real answer a pilot wants before
 * takeoff, not after.
 *
 * The file is generated by scripts/build-navdata.mjs from the OurAirports CSVs.
 * If it is absent, this reports absent. It does not fall back to a small
 * built-in table, which would be a synthetic navdata path wearing a helpful
 * face.
 */

import { bundleStatus } from './manifest.js';

export const NAVDATA_URL = '/data/navdata.json';

export async function loadNavdata(fetchImpl = fetch) {
  const status = await bundleStatus('navdata', fetchImpl);
  if (!status.present) {
    return { ok: false, reason: status.reason ?? 'navdata bundle not present', detail: status.detail ?? null };
  }
  try {
    const res = await fetchImpl(status.path ?? NAVDATA_URL, { cache: 'force-cache' });
    if (!res.ok) {
      return {
        ok: false,
        reason: `the data manifest says navdata is present but ${status.path ?? NAVDATA_URL} returned HTTP ${res.status}`,
      };
    }
    const body = await res.json();
    const counts = body?.meta?.counts;
    if (!body?.meta || !Array.isArray(body.airports)) {
      return { ok: false, reason: 'navdata bundle is present but malformed (no meta/airports)' };
    }
    return {
      ok: true,
      meta: body.meta,
      counts: counts ?? {
        airports: body.airports.length,
        runways: body.runways?.length ?? 0,
        navaids: body.navaids?.length ?? 0,
      },
      data: body,
    };
  } catch (err) {
    return { ok: false, reason: `navdata bundle unreadable: ${err.message}` };
  }
}
